import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function TeacherDashboard() {
  const { user, logout, API } = useAuth();
  const navigate = useNavigate();
  const [subject, setSubject] = useState('');
  const [qrCode, setQrCode] = useState(null);
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [countdown, setCountdown] = useState(0);
  const [autoRenew, setAutoRenew] = useState(false);
  const timerRef = useRef(null);
  const autoRenewRef = useRef(false);

  // Keep ref in sync with state for interval callback
  useEffect(() => { autoRenewRef.current = autoRenew; }, [autoRenew]);

  // ── Generate QR Code ────────────────────────────
  const generateQR = useCallback(async (subjectName) => {
    const subj = subjectName || subject;
    if (!subj.trim()) return;
    setLoading(true);
    setError('');
    try {
      const res = await API.post('/qr/generate', { subject: subj });
      setQrCode(res.data.qr);
      setSession(res.data.session);
      startCountdown(res.data.session.ttlSeconds);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to generate QR');
    } finally {
      setLoading(false);
    }
  }, [subject, API]);

  // ── Start countdown ─────────────────────────────
  const startCountdown = (seconds) => {
    if (timerRef.current) clearInterval(timerRef.current);
    setCountdown(seconds);
    timerRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(timerRef.current);
          timerRef.current = null;
          // Auto-regenerate if enabled
          if (autoRenewRef.current) {
            // Use the current subject from state
            setQrCode(null);
            setSession(null);
          }
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  // Auto-regenerate when countdown hits 0 and autoRenew is on
  useEffect(() => {
    if (countdown === 0 && autoRenewRef.current && subject.trim()) {
      generateQR(subject);
    }
  }, [countdown, subject, generateQR]);

  // ── End session manually ────────────────────────
  const endSession = async () => {
    if (!session) return;
    try {
      await API.put('/qr/end', { sessionId: session.sessionId });
      setQrCode(null);
      setSession(null);
      setCountdown(0);
      if (timerRef.current) clearInterval(timerRef.current);
      setAutoRenew(false);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to end session');
    }
  };

  // ── Handle form submit ──────────────────────────
  const handleSubmit = (e) => {
    e.preventDefault();
    generateQR();
  };

  // ── Toggle auto-renew ───────────────────────────
  const toggleAutoRenew = () => {
    setAutoRenew((prev) => !prev);
  };

  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1>👨‍🏫 Teacher Dashboard</h1>
        <div>
          <span style={styles.userInfo}>{user?.name}</span>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.content}>
        {/* ── QR Generator ── */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>{qrCode ? '🔄 Regenerate QR' : 'Generate QR Code'}</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <input
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              placeholder="Enter subject name (e.g., Mathematics)"
              style={styles.input}
              required
            />
            <button type="submit" disabled={loading} style={styles.button}>
              {loading ? 'Generating...' : qrCode ? '🔄 Generate New' : '🎯 Generate QR'}
            </button>
          </form>
          {error && <div style={styles.error}>{error}</div>}
        </div>

        {/* ── QR Code Display ── */}
        {qrCode && session && (
          <div style={styles.card}>
            <div style={styles.qrHeader}>
              <h2 style={styles.cardTitle}>📸 Scan this QR</h2>
              <div style={styles.badge}>LIVE</div>
            </div>
            <div style={styles.qrContainer}>
              <img src={qrCode} alt="Attendance QR Code" style={styles.qrImage} />
            </div>
            <p style={styles.sessionInfo}>
              <strong>{session.subject}</strong> — Expires in{' '}
              <span style={{ color: countdown < 10 ? '#ff6b6b' : '#6c63ff', fontSize: '1.3rem', fontWeight: 'bold' }}>
                {countdown}s
              </span>
            </p>
            <p style={{ fontSize: '0.75rem', color: '#666', textAlign: 'center', fontFamily: 'monospace' }}>
              Session: {session.sessionId.slice(0, 20)}...
            </p>

            {/* ── Auto-renew toggle ── */}
            <div style={styles.autoRenewRow}>
              <label style={styles.switch}>
                <input
                  type="checkbox"
                  checked={autoRenew}
                  onChange={toggleAutoRenew}
                />
                <span style={styles.slider}></span>
              </label>
              <span style={{ fontSize: '0.9rem', color: '#ccc' }}>
                Auto-regenerate on expiry
              </span>
            </div>

            {/* ── End session button ── */}
            <button onClick={endSession} style={styles.endBtn}>
              🛑 End Session
            </button>
          </div>
        )}

        {/* ── Quick info ── */}
        {!qrCode && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>ℹ️ How it works</h2>
            <ol style={{ color: '#aaa', lineHeight: '1.8', paddingLeft: '20px' }}>
              <li>Enter the subject name and click <strong>Generate QR</strong></li>
              <li>Students scan the QR with their phones</li>
              <li>Attendance is verified via <strong>GPS location</strong></li>
              <li>Enable <strong>Auto-regenerate</strong> for continuous sessions</li>
              <li>Use <strong>End Session</strong> to stop manually</li>
            </ol>
          </div>
        )}
      </div>
    </div>
  );
}

